-- Direct PostgreSQL regression: actual responsible synchronizer + FK + RLS.
-- Does not replace browser/PostgREST acceptance.
\set ON_ERROR_STOP on
DO $$ BEGIN IF current_database()<>'wk_head_rh_permission_test' THEN RAISE EXCEPTION 'isolated fixture required'; END IF; END $$;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',false);
DO $test$ BEGIN INSERT INTO people(id,workspace_id,owner_id,created_by,full_name) VALUES ('90000000-0000-4000-8000-000000000070','184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','Synthetic person'); RAISE NOTICE 'SAVE PASS 1: same payload as upsertPerson succeeds'; END $test$;
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM people WHERE id='90000000-0000-4000-8000-000000000070' AND assigned_to='90000000-0000-4000-8000-000000000003' AND owner_id='184b9435-0a9b-4334-9e89-8854dc883f5d' AND workspace_id='184b9435-0a9b-4334-9e89-8854dc883f5d') THEN RAISE EXCEPTION 'wrong responsible'; END IF; RAISE NOTICE 'SAVE PASS 2: actor is responsible; legacy owner and workspace preserved'; END $test$;
DO $test$ BEGIN INSERT INTO people_onboarding_plans(workspace_id,owner_id,person_id,kind) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000070','onboarding'); RAISE NOTICE 'SAVE PASS 3: new person can receive onboarding with production trigger'; END $test$;
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM people_onboarding_plans WHERE person_id='90000000-0000-4000-8000-000000000070' AND assigned_to='90000000-0000-4000-8000-000000000003') THEN RAISE EXCEPTION 'plan not visible or wrong actor'; END IF; RAISE NOTICE 'SAVE PASS 4: plan returned and readable with valid assigned_to FK'; END $test$;
DO $test$ BEGIN INSERT INTO people_onboarding_plans(workspace_id,owner_id,person_id,kind) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000005','onboarding'); RAISE NOTICE 'SAVE PASS 5: existing person can receive onboarding'; END $test$;
DO $test$ BEGIN INSERT INTO people(workspace_id,owner_id,created_by,assigned_to,full_name) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000004','Explicit user'); RAISE NOTICE 'SAVE PASS 6: explicit valid responsible preserved'; END $test$;
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM people WHERE full_name='Explicit user' AND assigned_to='90000000-0000-4000-8000-000000000004') THEN RAISE EXCEPTION 'explicit user changed'; END IF; RAISE NOTICE 'SAVE PASS 7: chosen user not overwritten'; END $test$;
DO $test$ BEGIN INSERT INTO people(workspace_id,owner_id,created_by,assigned_to,full_name) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000003','Explicit actor'); RAISE NOTICE 'SAVE PASS 8: new client explicit actor payload supported'; END $test$;
DO $test$ BEGIN BEGIN INSERT INTO people(workspace_id,owner_id,created_by,assigned_to,full_name) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000099','Invalid user'); RAISE EXCEPTION 'expected FK'; EXCEPTION WHEN foreign_key_violation THEN NULL; END; RAISE NOTICE 'SAVE PASS 9: invalid user UUID still rejected'; END $test$;
DO $test$ BEGIN IF has_function_privilege('authenticated','public.wk_people_responsible_actor()','execute') OR has_function_privilege('anon','public.wk_people_responsible_actor()','execute') THEN RAISE EXCEPTION 'direct trigger execution allowed'; END IF; RAISE NOTICE 'SAVE PASS 10: no direct public trigger execute'; END $test$;
RESET ROLE; UPDATE workspace_members SET status='inactive' WHERE workspace_id='184b9435-0a9b-4334-9e89-8854dc883f5d' AND user_id='90000000-0000-4000-8000-000000000003'; SET ROLE authenticated;
DO $test$ BEGIN BEGIN INSERT INTO people(workspace_id,owner_id,created_by,full_name) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','Inactive'); RAISE EXCEPTION 'expected RLS'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; RAISE NOTICE 'SAVE PASS 11: inactive actor remains denied'; END $test$;
RESET ROLE; UPDATE workspace_members SET status='active' WHERE workspace_id='184b9435-0a9b-4334-9e89-8854dc883f5d' AND user_id='90000000-0000-4000-8000-000000000003'; SELECT set_config('request.jwt.claim.sub','',false);
DO $test$ BEGIN INSERT INTO people(workspace_id,owner_id,created_by,full_name) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','90000000-0000-4000-8000-000000000003','Trusted import creator'); RAISE NOTICE 'SAVE PASS 12: trusted import uses valid active created_by'; END $test$;
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM people WHERE full_name='Trusted import creator' AND assigned_to='90000000-0000-4000-8000-000000000003') THEN RAISE EXCEPTION 'wrong import actor'; END IF; RAISE NOTICE 'SAVE PASS 13: import fallback references actual user'; END $test$;
DO $test$ BEGIN INSERT INTO people(workspace_id,owner_id,full_name) VALUES ('184b9435-0a9b-4334-9e89-8854dc883f5d','184b9435-0a9b-4334-9e89-8854dc883f5d','Import without actor'); RAISE NOTICE 'SAVE PASS 14: trusted import without actor leaves optional responsible empty'; END $test$;
DO $test$ BEGIN IF NOT EXISTS(SELECT 1 FROM people WHERE full_name='Import without actor' AND assigned_to IS NULL) THEN RAISE EXCEPTION 'invented responsible'; END IF; RAISE NOTICE 'SAVE PASS 15: no invented user for missing actor'; END $test$;
